require_once __DIR__ . '/_layout.php'; requirePermission('pricing.manage');
if(requestMethod()==='POST'){requireCsrfPost();try{$agencyId=(int)($_POST['agency_id']??0);requireAgencyAccess($agencyId);$value=positiveMoney($_POST['adjustment_value']??'');if($value===null)throw new InvalidArgumentException(t('validation.pricing_value'));dbExecute("INSERT INTO pricing_rules(agency_id,category_id,name,rule_type,priority,starts_at,ends_at,conditions_json,adjustment_type,adjustment_value,status,created_by)VALUES(:agency,:category,:name,:type,:priority,:starts,:ends,:conditions,:adjustment_type,:value,'active',:user)",['agency'=>$agencyId,'category'=>($_POST['category_id']??'')?:null,'name'=>trim((string)($_POST['name']??'')),'type'=>validateChoice($_POST['rule_type']??'',['seasonal','weekend','holiday','duration','business','partner','loyalty','delivery','young_driver','mileage','late_return','other'],'other'),'priority'=>(int)($_POST['priority']??100),'starts'=>($_POST['starts_at']??'')?:null,'ends'=>($_POST['ends_at']??'')?:null,'conditions'=>json_encode(['minimum_days'=>(int)($_POST['minimum_days']??0),'maximum_days'=>(int)($_POST['maximum_days']??0)],JSON_UNESCAPED_UNICODE),'adjustment_type'=>validateChoice($_POST['adjustment_type']??'',['fixed','percentage'],'fixed'),'value'=>$value,'user'=>currentUserId()]);auditLog('pricing_rule.created','pricing_rule',db()->lastInsertId(),null,['name'=>$_POST['name'],'value'=>$value],$agencyId);flash('success',t('message.pricing_created'));}catch(InvalidArgumentException|DomainException $exception){flash('danger',$exception->getMessage());}catch(Throwable $exception){reportDatabaseError($exception,'Pricing operation failed');flash('danger',t('message.pricing_failed'));}safeRedirect('pricing.php');}$ids=currentAgencyIds();if(!$ids)$ids=[0];$ph=implode(',',array_fill(0,count($ids),'?'));$agencies=dbFetchAll("SELECT id,name FROM agencies WHERE id IN ($ph)",$ids);$categories=dbFetchAll("SELECT id,name FROM vehicle_categories WHERE agency_id IN ($ph) OR agency_id IS NULL",$ids);$rules=dbFetchAll("SELECT pr.*,a.name agency_name,vc.name category_name FROM pricing_rules pr JOIN agencies a ON a.id=pr.agency_id LEFT JOIN vehicle_categories vc ON vc.id=pr.category_id WHERE pr.agency_id IN ($ph) AND pr.archived_at IS NULL ORDER BY pr.priority,pr.name",$ids);backofficeHeader(t('nav.pricing'),'pricing.php');?><?php pageHeader('page.pricing.title', 'page.pricing.description', ['breadcrumbs'=>[['label'=>'nav.commercial'],['label'=>'nav.pricing']],'primary'=>['label'=>'action.create_rule','href'=>'#new-pricing-rule']]); ?><div class="grid"><section class="card" id="new-pricing-rule"><div class="section-card-header"><h2><?=navigationIcon('commercial')?><?=e(t('section.new_pricing_rule'))?></h2></div><form method="post"><?=csrfField()?><label><?=e(t('field.agency'))?><select name="agency_id"><?php foreach($agencies as $a):?><option value="<?=e($a['id'])?>"><?=e($a['name'])?></option><?php endforeach;?></select></label><label><?=e(t('field.category'))?><select name="category_id"><option value=""><?=e(t('common.all_categories'))?></option><?php foreach($categories as $c):?><option value="<?=e($c['id'])?>"><?=e($c['name'])?></option><?php endforeach;?></select></label><label><?=e(t('field.name'))?><input name="name" required></label><label><?=e(t('field.rule_type'))?><select name="rule_type"><?php foreach(['seasonal','weekend','holiday','duration','business','partner','loyalty','delivery','young_driver','mileage','late_return','other'] as $type):?><option value="<?=e($type)?>"><?=e(t('option.'.$type))?></option><?php endforeach;?></select></label><label><?=e(t('field.minimum_days'))?><input type="number" name="minimum_days" min="0"></label><label><?=e(t('field.maximum_days'))?><input type="number" name="maximum_days" min="0"></label><label><?=e(t('field.start_date'))?><input type="datetime-local" name="starts_at"></label><label><?=e(t('field.end_date'))?><input type="datetime-local" name="ends_at"></label><label><?=e(t('field.adjustment'))?><select name="adjustment_type"><option value="fixed"><?=e(t('option.fixed'))?></option><option value="percentage"><?=e(t('option.percentage'))?></option></select></label><label><?=e(t('field.value'))?><input name="adjustment_value" required inputmode="decimal"></label><label><?=e(t('field.priority'))?><input type="number" name="priority" value="100"></label><button class="btn primary"><?=e(t('action.create_rule'))?></button></form></section><section class="card"><div class="section-card-header"><h2><?=navigationIcon('commercial')?><?=e(t('section.pricing_rules'))?></h2></div><div class="table-wrap"><table><tr><th><?=e(t('field.agency'))?></th><th><?=e(t('field.name'))?></th><th><?=e(t('field.type'))?></th><th><?=e(t('field.category'))?></th><th><?=e(t('field.adjustment'))?></th><th><?=e(t('field.period'))?></th><th><?=e(t('common.status'))?></th></tr><?php foreach($rules as $r):?><tr><td><?=e($r['agency_name'])?></td><td><?=e($r['name'])?></td><td><?=e(t('option.'.$r['rule_type']))?></td><td><?=e($r['category_name']?:t('common.all'))?></td><td><bdi><?=e(t('option.'.$r['adjustment_type']).' '.$r['adjustment_value'])?></bdi></td><td><?=formattedDateTime($r['starts_at'])?><br><?=formattedDateTime($r['ends_at'])?></td><td><?=statusBadge($r['status'])?></td></tr><?php endforeach;?></table><?php if(!$rules)echo emptyState('empty.no_records');?></div></section></div><?php backofficeFooter();
